1	//! Regression test for `commits_since_with_pathspec`'s revwalk bounding.
2	//! Isolated in its own integration-test binary because
3	//! `callisto_vcs::revwalk_visit_count` is a process-global counter that
4	//! other, non-`#[serial]` tests in a shared binary would pollute (see
5	//! `crates/callisto-graph/tests/apply_persist_open_count_test.rs` for the
6	//! precedent this file follows).
7	
8	use std::path::Path;
9	
10	use callisto_model::CommitSha;
11	use callisto_vcs::GitRepository;
12	use serial_test::serial;
13	
14	fn run_git(dir: &Path, args: &[&str]) {
15	    let status = std::process::Command::new("git")
16	        .args(args)
17	        .current_dir(dir)
18	        .status()
19	        .expect("git must be installed to run this test");
20	    assert!(status.success(), "git {args:?} failed in {dir:?}");
21	}
22	
23	fn init_repo(root: &Path) {
24	    run_git(root, &["init", "-q"]);
25	    run_git(root, &["config", "user.email", "test@example.com"]);
26	    run_git(root, &["config", "user.name", "Test"]);
27	}
28	
29	fn commit(root: &Path, n: usize) {
30	    std::fs::write(root.join("f.txt"), format!("commit {n}\n")).unwrap();
31	    run_git(root, &["add", "."]);
32	    run_git(root, &["commit", "-q", "-m", &format!("commit {n}")]);
33	}
34	
35	/// Spec: `commits_since_with_pathspec` must bound its walk to `since..HEAD`
36	/// -- not walk the whole repository history and filter after the fact. 30
37	/// linear commits precede `since`; 3 more follow it. Under the old
38	/// two-full-walk-then-exclude implementation, the primary revwalk visits
39	/// every one of the 33 commits reachable from HEAD regardless of `since`.
40	/// The bounded implementation must visit only the small number of commits
41	/// between `since` and HEAD.
42	#[test]
43	#[serial]
44	fn commits_since_with_pathspec_bounds_walk_to_since_head_range() {
45	    let ws_dir = tempfile::tempdir().unwrap();
46	    let root = ws_dir.path();
47	    init_repo(root);
48	
49	    for n in 1..=30 {
50	        commit(root, n);
51	    }
52	
53	    let since_output = std::process::Command::new("git")
54	        .args(["rev-parse", "HEAD"])
55	        .current_dir(root)
56	        .output()
57	        .unwrap();
58	    assert!(since_output.status.success());
59	    let since_sha = CommitSha::parse(String::from_utf8_lossy(&since_output.stdout).trim()).unwrap();
60	
61	    for n in 31..=33 {
62	        commit(root, n);
63	    }
64	
65	    let repo = GitRepository::discover(root).unwrap();
66	
67	    callisto_vcs::reset_revwalk_visit_count();
68	    let commits = repo.commits_since_with_pathspec(Some(&since_sha), &[]).unwrap();
69	
70	    assert_eq!(commits.len(), 3, "must return exactly the 3 commits after `since`");
71	
72	    assert_eq!(
73	        callisto_vcs::revwalk_visit_count(),
74	        3,
75	        "revwalk must visit exactly the 3 commits between `since` and HEAD, not the full 33-commit history"
76	    );
77	}
78	
[/external_agent_tool_result]

