18	pub(crate) fn check_exit_code_raw(report: &StatusReport) -> u8 {
19	    let has_pending = report.packages.iter().any(|p| !p.pending_changesets.is_empty());
20	    if has_pending {
21	        1
22	    } else {
23	        2
24	    }
